CREATE OR ALTER PROCEDURE [dbo].[InsertarPuntosPorFechaEmpresa]
    @FechaPedido DATE,
    @IdEmpresa INT,
    @TotalPuntos DECIMAL(10, 2),
    @ValorPorPunto DECIMAL(10, 2)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalEmpresa DECIMAL(18,2);
    DECLARE @PuntosDisponibles INT = @TotalPuntos;

    -- Verificar si hay pedidos para la empresa en la fecha
    IF NOT EXISTS (
        SELECT 1 
        FROM C_Pedidos P
        WHERE P.FechaPedido = @FechaPedido 
        AND P.IdEmpresa = @IdEmpresa
    )
    BEGIN
        RAISERROR('No hay pedidos para esa empresa en esa fecha.', 16, 1);
        RETURN;
    END

    -- Crear tabla temporal para calcular totales por pedido
    CREATE TABLE #PedidosConTotales (
        IdPedido INT PRIMARY KEY,
        TotalPedido DECIMAL(18,2),
        TotalEmpresa DECIMAL(18,2),
        Porcentaje DECIMAL(10,4),
        PuntosAsignados INT,
        ValorDolares DECIMAL(18,2)
    );

    -- Insertar pedidos con sus totales
    INSERT INTO #PedidosConTotales (IdPedido, TotalPedido)
    SELECT 
        P.IdPedido,
        ISNULL(SUM(DP.ValorCompra), 0) AS TotalPedido
    FROM C_Pedidos P
    LEFT JOIN C_DetallePedido DP ON P.IdPedido = DP.IdPedido
    WHERE P.FechaPedido = @FechaPedido 
        AND P.IdEmpresa = @IdEmpresa
    GROUP BY P.IdPedido;

    -- Calcular total de la empresa
    SELECT @TotalEmpresa = SUM(TotalPedido)
    FROM #PedidosConTotales;

    -- Si no hay total o es cero, retornar error
    IF @TotalEmpresa IS NULL OR @TotalEmpresa = 0
    BEGIN
        DROP TABLE #PedidosConTotales;
        RAISERROR('El total de los pedidos es cero. No se pueden asignar puntos.', 16, 1);
        RETURN;
    END

    -- Actualizar los pedidos con los puntos calculados
    UPDATE P
    SET 
        PuntosUtilizados = @PuntosDisponibles,
        ValorDolaresPuntos = @ValorPorPunto
    FROM C_Pedidos P
    INNER JOIN #PedidosConTotales T ON P.IdPedido = T.IdPedido;

    -- Limpiar tabla temporal
    DROP TABLE #PedidosConTotales;

END

