CREATE OR ALTER PROCEDURE [dbo].[Se_DetallePedido]
    @CodigoArticulo NVARCHAR(MAX),
    @DescripcionArticulo NVARCHAR(MAX),
    @Peso DECIMAL(18,2),
    @IdArticulo INT,
    @TallaColor NVARCHAR(MAX),
    @ValorCompra DECIMAL(18,2) NULL,
    @CantidadArticulos INT,
    @Link NVARCHAR(MAX) NULL,
    @NoPedidoAplicacion NVARCHAR(MAX) NULL,
    @IdDetallePedido INT
AS
BEGIN
    UPDATE [dbo].[C_DetallePedido]
    SET 
        [CodigoArticulo] = @CodigoArticulo,
        [DescripcionArticulo] = @DescripcionArticulo,
        [Peso] = @Peso,
        [IdArticulo] = @IdArticulo,
        [TallaColor] = @TallaColor,
        [ValorCompra] = @ValorCompra,
        [CantidadArticulos] = @CantidadArticulos,
        [Link] = @Link,
        [NoPedidoAplicacion] = @NoPedidoAplicacion,
        [ValorCompraLempiras] = ISNULL(@ValorCompra, 0) * ISNULL((SELECT P.TasaCambio FROM C_Pedidos P WHERE P.IdPedido = C_DetallePedido.IdPedido), 26.0),
